"use client";

import "./data-table.css";
import {
  ArrowDown,
  ArrowUp,
  ArrowUpDown,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
  Search,
} from "lucide-react";
import React, { useMemo, useState } from "react";
import { cn } from "@/lib/cn";

import { Checkbox } from "../checkbox";
import { TableBody, TableCell, TableHead, TableHeader, TableRoot, TableRow } from "../table";
import { DataTableContext, useDataTableContext } from "./data-table.context";
import { dataTableVariants, type DataTableVariants } from "./data-table.variants";

export type ColumnDef<T> = {
  id: string;
  header: React.ReactNode | ((props: { column: ColumnDef<T> }) => React.ReactNode);
  cell: (props: { row: T; index: number }) => React.ReactNode;
  sortable?: boolean;
  accessorKey?: keyof T;
};

export type DataTableRootProps = DataTableVariants & React.HTMLAttributes<HTMLDivElement>;

export const DataTableRoot = ({ children, className, size, ...props }: DataTableRootProps) => {
  const slots = dataTableVariants({ size });

  return (
    <DataTableContext.Provider value={{ slots }}>
      <div className={cn(slots.root(), className)} {...props}>
        {children}
      </div>
    </DataTableContext.Provider>
  );
};

export type DataTableToolbarProps = React.HTMLAttributes<HTMLDivElement>;

export const DataTableToolbar = ({ className, ...props }: DataTableToolbarProps) => {
  const { slots } = useDataTableContext();
  return <div className={cn(slots.toolbar(), className)} {...props} />;
};

export type DataTableSearchProps = React.InputHTMLAttributes<HTMLInputElement> & {
  onSearchChange?: (query: string) => void;
};

export const DataTableSearch = ({
  className,
  placeholder = "Filter...",
  onSearchChange,
  onChange,
  ...props
}: DataTableSearchProps) => {
  const { slots } = useDataTableContext();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange?.(e);
    onSearchChange?.(e.target.value);
  };

  return (
    <div className={cn(slots.search(), className)}>
      <Search />
      <input placeholder={placeholder} onChange={handleChange} {...props} />
    </div>
  );
};

export type DataTableColumnHeaderProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  sortDirection?: "asc" | "desc" | null;
  onToggleSort?: () => void;
};

export const DataTableColumnHeader = ({
  children,
  className,
  sortDirection,
  onToggleSort,
  ...props
}: DataTableColumnHeaderProps) => {
  const { slots } = useDataTableContext();

  return (
    <button
      type="button"
      className={cn(slots.columnHeader(), className)}
      onClick={onToggleSort}
      {...props}
    >
      {children}
      {sortDirection === "asc" && <ArrowUp />}
      {sortDirection === "desc" && <ArrowDown />}
      {sortDirection === null && <ArrowUpDown className="opacity-40" />}
    </button>
  );
};

export type DataTablePaginationProps = {
  pageIndex: number;
  pageCount: number;
  pageSize: number;
  totalItems: number;
  selectedCount?: number;
  onPageChange: (page: number) => void;
};

export const DataTablePagination = ({
  pageIndex,
  pageCount,
  pageSize,
  totalItems,
  selectedCount = 0,
  onPageChange,
}: DataTablePaginationProps) => {
  const { slots } = useDataTableContext();

  const startItem = pageIndex * pageSize + 1;
  const endItem = Math.min((pageIndex + 1) * pageSize, totalItems);

  return (
    <div className={slots.pagination()}>
      <div className={slots.paginationInfo()}>
        {selectedCount > 0 && (
          <span className="text-foreground mr-2 font-medium">{selectedCount} row(s) selected.</span>
        )}
        {totalItems > 0 ? (
          <span>
            Showing {startItem}-{endItem} of {totalItems} items
          </span>
        ) : (
          <span>No items to display</span>
        )}
      </div>

      <div className={slots.paginationControls()}>
        <button
          type="button"
          className={slots.pageButton()}
          disabled={pageIndex === 0}
          onClick={() => onPageChange(0)}
          title="First page"
        >
          <ChevronsLeft />
        </button>
        <button
          type="button"
          className={slots.pageButton()}
          disabled={pageIndex === 0}
          onClick={() => onPageChange(pageIndex - 1)}
          title="Previous page"
        >
          <ChevronLeft />
        </button>
        <span className="px-2 text-xs">
          Page {pageIndex + 1} of {Math.max(pageCount, 1)}
        </span>
        <button
          type="button"
          className={slots.pageButton()}
          disabled={pageIndex >= pageCount - 1}
          onClick={() => onPageChange(pageIndex + 1)}
          title="Next page"
        >
          <ChevronRight />
        </button>
        <button
          type="button"
          className={slots.pageButton()}
          disabled={pageIndex >= pageCount - 1}
          onClick={() => onPageChange(pageCount - 1)}
          title="Last page"
        >
          <ChevronsRight />
        </button>
      </div>
    </div>
  );
};

export type DataTableProps<T> = {
  data: T[];
  columns: ColumnDef<T>[];
  searchable?: boolean;
  searchPlaceholder?: string;
  enableSelection?: boolean;
  pageSize?: number;
  className?: string;
  emptyMessage?: React.ReactNode;
  onRowClick?: (row: T) => void;
};

export function DataTable<T extends Record<string, any>>({
  data,
  columns,
  searchable = true,
  searchPlaceholder = "Search data...",
  enableSelection = false,
  pageSize = 5,
  className,
  emptyMessage = "No results found.",
  onRowClick,
}: DataTableProps<T>) {
  const [searchQuery, setSearchQuery] = useState("");
  const [sortColumn, setSortColumn] = useState<string | null>(null);
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("asc");
  const [pageIndex, setPageIndex] = useState(0);
  const [selectedRows, setSelectedRows] = useState<Set<number>>(new Set());

  // Filter
  const filteredData = useMemo(() => {
    if (!searchQuery.trim()) return data;
    const q = searchQuery.toLowerCase();
    return data.filter((row) =>
      Object.values(row).some((val) =>
        String(val ?? "")
          .toLowerCase()
          .includes(q),
      ),
    );
  }, [data, searchQuery]);

  // Sort
  const sortedData = useMemo(() => {
    if (!sortColumn) return filteredData;
    const col = columns.find((c) => c.id === sortColumn);
    if (!col) return filteredData;

    return [...filteredData].sort((a, b) => {
      const aVal = col.accessorKey ? a[col.accessorKey] : a[col.id];
      const bVal = col.accessorKey ? b[col.accessorKey] : b[col.id];

      if (aVal === bVal) return 0;
      if (aVal === null || aVal === undefined) return 1;
      if (bVal === null || bVal === undefined) return -1;

      const comp = aVal < bVal ? -1 : 1;
      return sortDirection === "asc" ? comp : -comp;
    });
  }, [filteredData, sortColumn, sortDirection, columns]);

  // Paginate
  const pageCount = Math.ceil(sortedData.length / pageSize);
  const paginatedData = useMemo(() => {
    const start = pageIndex * pageSize;
    return sortedData.slice(start, start + pageSize);
  }, [sortedData, pageIndex, pageSize]);

  const handleToggleSort = (colId: string) => {
    if (sortColumn === colId) {
      if (sortDirection === "asc") setSortDirection("desc");
      else setSortColumn(null);
    } else {
      setSortColumn(colId);
      setSortDirection("asc");
    }
  };

  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      const allIndices = new Set(sortedData.map((_, i) => i));
      setSelectedRows(allIndices);
    } else {
      setSelectedRows(new Set());
    }
  };

  const handleSelectRow = (index: number, checked: boolean) => {
    const next = new Set(selectedRows);
    if (checked) next.add(index);
    else next.delete(index);
    setSelectedRows(next);
  };

  const isAllSelected = sortedData.length > 0 && selectedRows.size === sortedData.length;

  return (
    <DataTableRoot className={className}>
      {searchable && (
        <DataTableToolbar>
          <DataTableSearch
            placeholder={searchPlaceholder}
            onSearchChange={(q) => {
              setSearchQuery(q);
              setPageIndex(0);
            }}
          />
        </DataTableToolbar>
      )}

      <div className="data-table__container">
        <TableRoot>
          <TableHeader>
            <TableRow>
              {enableSelection && (
                <TableHead className="w-10">
                  <Checkbox.Root
                    checked={isAllSelected}
                    onCheckedChange={(checked) => handleSelectAll(!!checked)}
                  >
                    <Checkbox.Indicator />
                  </Checkbox.Root>
                </TableHead>
              )}
              {columns.map((col) => (
                <TableHead key={col.id}>
                  {col.sortable ? (
                    <DataTableColumnHeader
                      sortDirection={sortColumn === col.id ? sortDirection : null}
                      onToggleSort={() => handleToggleSort(col.id)}
                    >
                      {typeof col.header === "function" ? col.header({ column: col }) : col.header}
                    </DataTableColumnHeader>
                  ) : typeof col.header === "function" ? (
                    col.header({ column: col })
                  ) : (
                    col.header
                  )}
                </TableHead>
              ))}
            </TableRow>
          </TableHeader>

          <TableBody>
            {paginatedData.length > 0 ? (
              paginatedData.map((row, i) => {
                const rowIndex = pageIndex * pageSize + i;
                const isSelected = selectedRows.has(rowIndex);

                return (
                  <TableRow
                    key={rowIndex}
                    data-state={isSelected ? "selected" : undefined}
                    className={onRowClick ? "cursor-pointer" : undefined}
                    onClick={() => onRowClick?.(row)}
                  >
                    {enableSelection && (
                      <TableCell className="w-10" onClick={(e) => e.stopPropagation()}>
                        <Checkbox.Root
                          checked={isSelected}
                          onCheckedChange={(checked) => handleSelectRow(rowIndex, !!checked)}
                        >
                          <Checkbox.Indicator />
                        </Checkbox.Root>
                      </TableCell>
                    )}
                    {columns.map((col) => (
                      <TableCell key={col.id}>{col.cell({ row, index: rowIndex })}</TableCell>
                    ))}
                  </TableRow>
                );
              })
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length + (enableSelection ? 1 : 0)}
                  className="text-muted-foreground h-24 text-center"
                >
                  {emptyMessage}
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </TableRoot>
      </div>

      <DataTablePagination
        pageIndex={pageIndex}
        pageCount={pageCount}
        pageSize={pageSize}
        totalItems={sortedData.length}
        selectedCount={selectedRows.size}
        onPageChange={setPageIndex}
      />
    </DataTableRoot>
  );
}

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const dataTableVariants = tv({
  slots: {
    root: "data-table",
    toolbar: "data-table__toolbar",
    search: "data-table__search",
    container: "data-table__container",
    pagination: "data-table__pagination",
    paginationInfo: "data-table__pagination-info",
    paginationControls: "data-table__pagination-controls",
    pageButton: "data-table__page-button",
    columnHeader: "data-table__column-header",
  },
  variants: {
    size: {
      sm: {
        root: "data-table--sm",
        search: "px-2.5 py-1 text-xs",
      },
      md: {
        root: "data-table--md",
      },
      lg: {
        root: "data-table--lg",
        search: "px-3.5 py-2 text-base",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type DataTableVariants = VariantProps<typeof dataTableVariants>;

"use client";

import { createContext, useContext } from "react";

import { dataTableVariants } from "./data-table.variants";

export type DataTableContextType = {
  slots: ReturnType<typeof dataTableVariants>;
};

export const DataTableContext = createContext<DataTableContextType | null>(null);

export const useDataTableContext = () => {
  const context = useContext(DataTableContext);
  return context ?? { slots: dataTableVariants() };
};

.data-table {
  @apply flex flex-col gap-4 w-full max-w-full;
}

.data-table__toolbar {
  @apply flex items-center justify-between gap-4 flex-wrap sm:flex-nowrap;
}

.data-table__search {
  @apply flex items-center gap-2 border border-border rounded-lg px-3 py-1.5 bg-background text-sm w-full sm:w-64 focus-within:ring-2 focus-within:ring-ring;
}

.data-table__search svg {
  @apply text-muted-foreground h-4 w-4 shrink-0;
}

.data-table__search input {
  @apply bg-transparent outline-none w-full placeholder:text-muted-foreground text-foreground;
}

.data-table__container {
  @apply rounded-lg border border-border overflow-x-auto max-w-full bg-background shadow-2xs w-full scrollbar-none;
}

.data-table__pagination {
  @apply flex items-center justify-between gap-3 px-2 py-2 flex-wrap text-sm text-muted-foreground;
}

.data-table__pagination-info {
  @apply flex items-center gap-1 text-xs sm:text-sm;
}

.data-table__pagination-controls {
  @apply flex items-center gap-1 sm:gap-2 flex-wrap;
}

.data-table__page-button {
  @apply inline-flex items-center justify-center rounded-md text-sm font-medium border border-border bg-background h-8 w-8 hover:bg-accent hover:text-accent-foreground disabled:opacity-50 disabled:pointer-events-none transition-colors shrink-0;
}

.data-table__page-button svg {
  @apply h-4 w-4;
}

.data-table__column-header {
  @apply inline-flex items-center gap-1.5 cursor-pointer select-none hover:text-foreground transition-colors font-medium whitespace-nowrap;
}

.data-table__column-header svg {
  @apply h-3.5 w-3.5 shrink-0;
}

import {
  DataTable,
  DataTableColumnHeader,
  DataTablePagination,
  DataTableRoot,
  DataTableSearch,
  DataTableToolbar,
} from "./data-table";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/data-table/content.md
 */
export const DataTableComponent = {
  ColumnHeader: DataTableColumnHeader,
  Pagination: DataTablePagination,
  Root: DataTableRoot,
  Search: DataTableSearch,
  Toolbar: DataTableToolbar,
};

export {
  DataTable,
  DataTableColumnHeader,
  DataTablePagination,
  DataTableRoot,
  DataTableSearch,
  DataTableToolbar,
};

export type {
  ColumnDef,
  DataTableColumnHeaderProps,
  DataTablePaginationProps,
  DataTableProps,
  DataTableRootProps,
  DataTableSearchProps,
  DataTableToolbarProps,
} from "./data-table";

export { DataTableContext, useDataTableContext } from "./data-table.context";
export { type DataTableVariants, dataTableVariants } from "./data-table.variants";
